func newClassicPatchPoliciesDeleteCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagYes    bool
		flagDryRun bool
	)

	cmd := &cobra.Command{
		Use:   "delete <id>",
		Short: "Delete a patch_policy",
		Example: `  # Delete a patch_policy (with confirmation)
  jamf-cli pro classic-patch-policies delete 1

  # Delete without confirmation prompt
  jamf-cli pro classic-patch-policies delete 1 --yes`,
		Annotations: map[string]string{"jamf:destructive": "true", "jamf:api": "pro-classic", "jamf:gateway-privileges": "patch-policies:delete"},
		Args:        cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			if flagDryRun {
				fmt.Fprintf(os.Stderr, "Would delete patch_policy %s\n", args[0])
				return nil
			}
			if !flagYes {
				noInput, _ := cmd.Flags().GetBool("no-input")
				if noInput {
					return fmt.Errorf("destructive operation requires --yes when --no-input is set")
				}
				fmt.Fprintf(os.Stderr, "This will delete patch_policy %s. Type 'yes' to confirm: ", args[0])
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			noInputForCooldown, _ := cmd.Flags().GetBool("no-input")
			if err := cooldown.Enforce(ctx.ProfileName, noInputForCooldown, ctx.DestructiveCooldown); err != nil {
				return err
			}
			path := fmt.Sprintf("/JSSResource/patchpolicies/id/%s", url.PathEscape(args[0]))

			resp, err := ctx.Client.Do(reqCtx, "DELETE", path, nil)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			if resp.StatusCode == http.StatusNoContent || resp.StatusCode == http.StatusOK {
				cooldown.Record(ctx.ProfileName)
				fmt.Fprintln(os.Stderr, "Deleted successfully")
				return nil
			}

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")

	return cmd
}
